('lookout', 'Čierna hora', 'Vrchol na Slovensku.', 49.16389, 20.80278, 'SK', 'wikidata-peaks-cz-sk-peak', 10000, null, 'Q31556033', '{"en": {"description": "Mountain summit in Slovakia."}, "de": {"description": "Berggipfel in der Slowakei."}, "pl": {"description": "Szczyt w Słowacji."}, "nl": {"description": "Bergtop in Slowakije."}, "es": {"description": "Cumbre en Eslovaquia."}, "fr": {"description": "Sommet en Slovaquie."}, "uk": {"description": "Вершина у Словаччині."}}'),
('lookout', 'Špičák', 'Vrchol v Česku.', 50.51501, 16.31534, 'CZ', 'wikidata-peaks-cz-sk-peak', 10000, null, 'Q23811973', '{"en": {"description": "Mountain summit in Czechia."}, "de": {"description": "Berggipfel in Tschechien."}, "pl": {"description": "Szczyt w Czechach."}, "nl": {"description": "Bergtop in Tsjechië."}, "es": {"description": "Cumbre en Chequia."}, "fr": {"description": "Sommet en Tchéquie."}, "uk": {"description": "Вершина у Чехії."}}')
) as v(category, name, description, lat, lng, country, source, sort_order,
       image_url, wikidata_id, translations)
where not exists (
  select 1 from public.points_of_interest p
   where p.lat between v.lat - 0.00225 and v.lat + 0.00225
     and p.lng between v.lng - 0.0035 and v.lng + 0.0035
     -- Dvojník = STEJNÝ normalizovaný název do ~250 m. Žádné plošné „cokoli
     -- do X metrů": právě to v dávce z 19. 9. vyhodilo Sněžku, protože na
     -- jejím vrcholu má Wikidata bod „Krkonošský národní park" s TOTOŽNÝMI
     -- souřadnicemi. Dva různé objekty na jednom bodě jsou legitimní data;
     -- na jeden špendlík je v seznamu i na mapě slučuje appka.
     and p.norm_name = public.poi_norm_name(v.name)
     and 111320.0 * sqrt(power(p.lat - v.lat, 2)
           + power((p.lng - v.lng) * cos(radians(v.lat)), 2)) <= 250
);
